mapper.select:
select uc.id, u.username, question, answer, c.name as categoryName, supplement, contact, CASE uc.status WHEN 0 THEN '待审核' WHEN 1 THEN '已通过' WHEN 2 THEN '已驳回' END as statusDesc, uc.created_time, uc.reviewed_time, uc.reject_reason from user_contribution uc left join category c on uc.category_id = c.id left join user u on uc.user_id = u.id
and uc.status = #{status}
and uc.category_id = #{categoryId}
and question like concat('%', #{keyword}, '%')
and u.username like concat('%', #{username}, '%')
and uc.created_time >= #{startTime}
and uc.created_time <= #{endTime}
order by uc.created_time
desc
asc
